# Separate editorial callouts; never presented as verbatim transcription.
notes=[
 ('تقسیم محوری و ضمیمه بر اساس جایگاه در محور بدن است؛ جمجمه، لامی و ستون مهره‌ها در محوری‌اند، اندام‌ها و کمربندهایشان ضمیمه‌اند.','در دو شکل جزوه ابتدا جمجمه و ستون مهره‌ها را پیدا کنید، سپس تغییر رنگ اندام‌ها را مقایسه کنید.',3),
 ('۲۲ استخوان جمجمه در شمار رایج شامل ۸ استخوان مغزی و ۱۴ استخوان صورت است؛ شش استخوانچهٔ گوش جداگانه شمرده می‌شوند.','لایهٔ اسفنجی میان دو صفحهٔ متراکم را دیپلوئه می‌نامند؛ برش نتر این لایه و پرده‌های زیر آن را در کنار هم نشان می‌دهد.',4),
 ('زوج بودن یعنی دو استخوان در دو طرف؛ فرد بودن یعنی یک استخوان در شمارش. در فهرست جزوه شاخک تحتانی بینی در متن اولیه جا افتاده و در مرور صفحهٔ ۲۰ آمده است.','لامی در گردن قرار دارد و در شمار ۲۲ استخوان جمجمه وارد نمی‌شود؛ آن را با مندیبل اشتباه نگیرید.',5),
 ('سقف و قاعده تقسیم فضایی‌اند؛ نوروکرانیوم و ویسروکرانیوم تقسیم بر اساس بخش مغزی و صورتی‌اند. این دو معیار را در یک ردیف یکسان قرار ندهید.','در تصویر نتر کالواریا را مانند درپوش برداشته‌شده تصور کنید؛ قاعده، کف فضای جمجمه در زیر آن است.',6),
 ('در نمای درونی قاعده، حفره‌های قدامی، میانی و خلفی را از جلو به عقب بخوانید؛ جابه‌جایی جهت نگاه نام حفره را تغییر نمی‌دهد.','صفحهٔ فرانکفورت از لبهٔ تحتانی کاسهٔ چشم و بخش فوقانی مجرای شنوایی خارجی می‌گذرد؛ آن را روی نمای جانبی تنظیم کنید.',7),
 ('نمای قدامی لزوماً همهٔ سطوح هر استخوان را نشان نمی‌دهد؛ آنچه دیده می‌شود سهم آن استخوان در همان نماست.','برای جهت‌یابی، لبهٔ بالایی کاسهٔ چشم را پیشانی و ناحیهٔ دندانی فک بالا را ماگزیلا قرار دهید.',8),
 ('گلابلا در خط میانی میان دو قوس ابرویی است؛ برجستگی پیشانی بالاتر قرار می‌گیرد. درز متوپیک پایدار را نباید خودبه‌خود شکستگی فرض کرد.','در شکل نوزاد، درز پیشانی از جلو به سوی ملاج قدامی می‌رود؛ با خط وسط تصویر جزوه مقایسه کنید.',9),
 ('حفرهٔ غدهٔ اشکی در قسمت قدامی‌ـ‌خارجی سقف کاسهٔ چشم و ناحیهٔ قرقره در قدام‌ـ‌داخل است.','تصویر کاسهٔ چشم را از روبه‌رو می‌بینید؛ داخل هر کاسه چشم به سمت بینی و خارج آن به سمت گیجگاه است.',10),
 ('خطوط گیجگاهی از ناحیهٔ زائدهٔ گونه‌ای به سمت بالا ادامه می‌یابند؛ بخش بینی پیشانی میان دو کاسهٔ چشم قرار دارد.','در برش تیغه، خط وسط بینی را از استخوان بینی به سمت تیغه و سپس به خار بینی قدامی دنبال کنید.',11),
 ('نازیون محل تلاقی درز بین‌بینی با درز پیشانی‌ـ‌بینی است؛ این نقطه با خار بینی قدامی در پایین دهانهٔ استخوانی یکی نیست.','استخوان بینی را در بالا و غضروف‌ها را در پایین شکل نتر پیدا کنید؛ مرز استخوانی و غضروفی را از هم جدا بنویسید.',12),
 ('ماگزیلا فقط سطح صورت نیست: سطح چشمی، بینی و زیرگیجگاهی آن به فضاهای متفاوت مجاورند.','قاعدهٔ هرم به سمت حفرهٔ بینی و رأس به سمت استخوان گونه است؛ با چرخاندن ذهنی نما، جای سطوح را دنبال کنید.',14),
 ('برای یادسپاری جهت‌ها: زائدهٔ پیشانی به بالا، گونه‌ای به خارج، آلوئولار به پایین و کامی به داخل می‌روند.','شمار سه زائده در متن صفحهٔ ۱۵ را با افزودن زائدهٔ کامی در صفحهٔ ۱۶ و فهرست چهارگانهٔ مرور مقایسه کنید.',15),
 ('اشک از کانالیکول‌ها به کیسهٔ اشکی و از مجرای بینی‌ـ‌اشکی به مجرای تحتانی بینی می‌ریزد.','ستیغ اشکی قدامی را جلوتر از حفرهٔ کیسه بیابید؛ مسیر کیسه و مجرا را در شکل نتر از بالا به پایین دنبال کنید.',15),
 ('زائده‌های کامی ماگزیلا بخش قدامی کام سخت را می‌سازند؛ صفحه‌های افقی استخوان کامی بخش خلفی را تکمیل می‌کنند.','سقف دهان هم‌زمان کف حفرهٔ بینی است؛ در تصویر تحتانی، آن را از جلو در امتداد قوس دندانی به عقب بخوانید.',16),
 ('دهانهٔ سینوس فکی نسبت به کف سینوس بالاتر است و کف آن با ریشهٔ دندان‌های فک بالا مجاورت دارد.','در برش، اول حفرهٔ بینی را وسط و سینوس را در خارج بیابید؛ سپس کف سینوس و دهانهٔ داخلی را از نظر ارتفاع مقایسه کنید.',17),
 ('تکوین دندان پیش از تولد آغاز می‌شود، ولی رویش اغلب پس از تولد رخ می‌دهد؛ این دو اصطلاح هم‌معنا نیستند.','شکل نتر رشد سینوس را در سنین مختلف نشان می‌دهد؛ ابعاد چهره و زمان تکامل میان افراد متفاوت‌اند.',18),
 ('مرور پایانی را به چهار دسته تقسیم کنید: شمار و طبقه‌بندی استخوان‌ها، پیشانی، بینی، و ماگزیلا و سینوس آن.','هنگام تحویل، برای هر دسته هم صفحهٔ متن اصلی و هم شکل مرتبط را ذکر کنید و توضیح افزوده را از متن جزوه جدا نگه دارید.',20),
]

def call(title,text,kind,src):return {'type':'callout','title':title,'text':text,'kind':kind,'src':src+' · نکتهٔ آموزشی افزوده'}
def table(head,rows,caption,src):return {'type':'table','head':head,'rows':rows,'caption':caption,'src':src+' · جدول آموزشی افزوده'}
